// src/components/User/HomePage.js

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { categories } from '../../mockData';
import './HomePage.css';

// Search Icon Component
function SearchIcon() {
  return (
    <svg className="search-icon" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor">
      <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-5.197-5.197m0 0A7.5 7.5 0 105.196 5.196a7.5 7.5 0 0010.607 10.607z" />
    </svg>
  );
}

// --- NEW MODAL COMPONENT ---
function InitialDetailsModal({ isOpen, onDetailsSubmit }) {
  const [name, setName] = useState('');
  const [persons, setPersons] = useState('2');
  const [address, setAddress] = useState('');
  const [contact, setContact] = useState('');

  if (!isOpen) return null;

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!name || !contact) {
      alert("Please enter your Name and Contact.");
      return;
    }
    
    // Pass the collected details up to the parent App component
    onDetailsSubmit({ name, persons, address, contact });
  };

  return (
    <div className="initial-modal-overlay">
      <form className="initial-modal-content" onSubmit={handleSubmit}>
        <h3>Enter Your Details</h3>
        
        <div className="form-group-modal">
          <label htmlFor="name">Name</label>
          <input id="name" type="text" placeholder="full name" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>

        <div className="form-group-modal">
          <label htmlFor="persons">Number of Person</label>
          <input id="persons" type="number" placeholder="2, 4, 6" value={persons} onChange={(e) => setPersons(e.target.value)} />
        </div>

        <div className="form-group-modal">
          <label htmlFor="address">Address (for Takeout)</label>
          <input id="address" type="text" placeholder="address" value={address} onChange={(e) => setAddress(e.target.value)} />
        </div>

        <div className="form-group-modal">
          <label htmlFor="contact">Contact</label>
          <input id="contact" type="tel" placeholder="phone" value={contact} onChange={(e) => setContact(e.target.value)} required />
        </div>
        
        <button type="submit" className="modal-order-btn">Order Now</button>
      </form>
    </div>
  );
}
// --- END NEW MODAL COMPONENT ---


// Main HomePage Component
function HomePage({ menu = [], cart = [], addToCart, isModalOpen, onDetailsSubmit }) {
  const navigate = useNavigate();
  const [activeCategory, setActiveCategory] = useState(categories[0]);
  const [searchTerm, setSearchTerm] = useState('');

  // Helper function to check item quantity in the cart
  const getItemQuantity = (itemId) => {
    const itemInCart = cart.find(i => i.id === itemId);
    return itemInCart ? itemInCart.quantity : 0;
  };

  // 1. Filter by Search Term
  const searchedMenu = menu.filter((item) =>
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // 2. Group the searched menu by category
  const menuByCategories = categories.map((category) => ({
    categoryName: category,
    items: searchedMenu.filter((item) => item.category === category),
  }));

  // Calculate cart total
  const cartTotalItems = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="mobile-container homepage">
      
      {/* RENDER THE MODAL AT THE TOP LEVEL */}
      <InitialDetailsModal isOpen={isModalOpen} onDetailsSubmit={onDetailsSubmit} />

      {/* Header */}
      <header className="home-header">
        <h1>Hello, Guest</h1>
        <p>What would you like to eat today?</p>
      </header>

      {/* Search Bar */}
      <div className="search-bar">
        <SearchIcon />
        <input
          type="text"
          placeholder="Search for food..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* Category Navigation */}
      <nav className="category-nav">
        {categories.map((category) => (
          <button
            key={category}
            className={`category-btn ${activeCategory === category ? 'active' : ''}`}
            onClick={() => setActiveCategory(category)}
          >
            {category}
          </button>
        ))}
      </nav>

      {/* Menu List */}
      <section className="menu-list">
        {menuByCategories.map(({ categoryName, items }) => {
          if (categoryName !== activeCategory) {
            return null;
          }
          
          return (
            <div key={categoryName} id={categoryName} className="category-section-wrapper">
              <h2>{categoryName}</h2>
              
              {items.length > 0 ? (
                <div className="category-grid">
                  {items.map((item) => {
                    const quantity = getItemQuantity(item.id);
                    
                    return (
                      <div key={item.id} className="menu-item">
                        <img src={item.image} alt={item.name} className="item-image" />
                        <div className="item-details">
                          <div className="item-info-wrapper">
                            <h3>{item.name}</h3>
                            <p>₹{item.price}</p>
                          </div>
                          
                          {/* CONDITIONAL RENDERING HERE */}
                          {quantity > 0 ? (
                            <div className="quantity-control-card">
                              {/* Using addToCart to handle quantity decrease (or removal if it hits 0) */}
                              <button 
                                onClick={() => addToCart({ ...item, quantity: quantity - 1 })}
                              >
                                −
                              </button>
                              <span>{quantity}</span>
                              <button 
                                onClick={() => addToCart({ ...item, quantity: quantity + 1 })}
                              >
                                +
                              </button>
                            </div>
                          ) : (
                            <button className="add-btn" onClick={() => addToCart(item)}>+</button>
                          )}

                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <p>No items found in this category.</p>
              )}
            </div>
          );
        })}
      </section>

      {/* Fixed Next Button */}
      {cartTotalItems > 0 && (
        <div className="next-button-container">
          <button className="next-btn" onClick={() => navigate('/checkout')}>
            {/* <span>{cartTotalItems} Item{cartTotalItems > 1 ? 's' : ''}</span> REMOVED */}
            <span>Next</span>
          </button>
        </div>
      )}

    </div>
  );
}

export default HomePage;
